BEGIN;

VALUES ('assombrado', 'Assombrado', 209)
ON CONFLICT (slug) DO UPDATE
SET name = excluded.name,
    source_page = excluded.source_page;

ON CONFLICT (id) DO UPDATE
SET name = excluded.name,
    category = excluded.category,
    subcategory = excluded.subcategory,
    data = excluded.data;

UPDATE public.equipment_items
SET data = jsonb_set(data, '{description}', '"Uma caixa de música que toca sozinha sempre que alguém que a segura dança."'::jsonb)
WHERE id = 'caixa-de-musica';

UPDATE public.equipment_items
SET data = jsonb_set(data, '{description}', '"Um brinquedo de mola com a manivela faltando."'::jsonb)
WHERE id = 'brinquedo-mecanico';

VALUES ('monster-hunter', 'Pacote de Caçador de Monstro', 4578, 209)
ON CONFLICT (id) DO UPDATE
SET name = excluded.name,
    price_cp = excluded.price_cp,
    source_page = excluded.source_page;

ON CONFLICT (pack_id, item_id) DO UPDATE SET quantity = excluded.quantity;

COMMIT;
